<?php use App\Core\TurkeyLocation; use App\Core\Auth;use App\Core\Csrf;require __DIR__.'/../layouts/header.php'; ?>
<main class="container section-space v9-page"><section class="v9-page-head"><div><span class="v9-eyebrow">CANLI OYUNCU HAVUZU</span><h1>Müsait Oyuncular</h1><p>Şu anda veya yakında sahaya çıkabilecek oyuncuları konum ve mevkiye göre gör.</p></div><?php if(Auth::id()):?><a class="btn btn-primary" href="/musaitim">Ben de Müsaitim</a><?php else:?><a class="btn btn-primary" href="/giris">Giriş Yap</a><?php endif;?></section>
<form class="v9-filterbar" method="get"><select name="province" data-location-province><?= TurkeyLocation::provinceOptions((string)($filters['province']??''),'Tüm iller') ?></select><select name="district" data-location-district data-empty-label="Tüm ilçeler"><?= TurkeyLocation::districtOptions((string)($filters['province']??''),(string)($filters['district']??''),'Tüm ilçeler') ?></select><select name="position"><option value="">Tüm mevkiler</option><?php foreach(\App\Models\PlayerAvailability::POSITIONS as $p):?><option <?= (($filters['position']??'')===$p)?'selected':'' ?>><?= htmlspecialchars($p) ?></option><?php endforeach;?></select><button class="btn btn-dark">Filtrele</button><a class="btn btn-ghost" href="/musait-oyuncular?all=1">Tümü</a></form>
<div class="availability-grid"><?php foreach(($players??[]) as $p):?><article class="availability-card"><div class="availability-card-top"><a class="avatar-block" href="/kariyer/<?= (int)$p['user_id'] ?>"><?php if(!empty($p['avatar_path'])):?><img src="<?= htmlspecialchars((string)$p['avatar_path'],ENT_QUOTES,'UTF-8') ?>" alt="<?= htmlspecialchars((string)$p['display_name'],ENT_QUOTES,'UTF-8') ?> profil fotoğrafı"><?php else:?><?= htmlspecialchars(strtoupper(substr((string)$p['display_name'],0,1))) ?><?php endif;?></a><div><strong><?= htmlspecialchars((string)$p['display_name']) ?></strong><small><?= htmlspecialchars((string)$p['position']) ?> · <?= htmlspecialchars((string)$p['district'].', '.$p['province']) ?></small></div><span class="live-chip">MÜSAİT</span></div><div class="availability-time"><b><?= date('H:i',strtotime((string)$p['starts_at'])) ?>–<?= date('H:i',strtotime((string)$p['ends_at'])) ?></b><span><?= date('d.m.Y',strtotime((string)$p['starts_at'])) ?></span></div><div class="availability-meta"><span><?= (int)$p['radius_km'] ?> km</span><?php if($p['dominant_foot']):?><span><?= htmlspecialchars((string)$p['dominant_foot']) ?> ayak</span><?php endif;?></div><?php if($p['note']):?><p><?= htmlspecialchars((string)$p['note']) ?></p><?php endif;?><?php if(!empty($managedTeams)):?><form class="availability-invite" method="post" action="/musait-oyuncular/<?= (int)$p['id'] ?>/davet"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(Csrf::token()) ?>"><select name="team_id" required><?php foreach($managedTeams as $t):?><option value="<?= (int)$t['id'] ?>"><?= htmlspecialchars((string)$t['name']) ?></option><?php endforeach;?></select><input name="message" maxlength="300" placeholder="Kısa davet notu (isteğe bağlı)"><button class="btn btn-primary btn-small">Maça Davet Et</button></form><?php elseif(Auth::id()):?><a class="btn btn-soft btn-small" href="/takim-olustur">Davet için takım oluştur</a><?php endif;?></article><?php endforeach;?><?php if(empty($players)):?><div class="v9-empty span-all"><strong>Bu filtrelerde aktif oyuncu yok.</strong><p>Filtreleri genişletebilir veya kendi müsaitlik durumunu yayınlayabilirsin.</p></div><?php endif;?></div></main>
